import * as s from "../core/validation/index.js";
import type { EnumSchema } from "../core/validation/schema.js";

/** Indicates the source that generated the gift card account number (GAN). */
export const GiftCardGanSource = {
  /** The GAN is generated by Square. */
  Square: "SQUARE",
  /**
   * The GAN is provided by a non-Square system. For more information, see [Custom
   * GANs](https://developer.squareup.com/docs/gift-cards/using-gift-cards-api#custom-gans) or
   * [Third-party gift
   * cards](https://developer.squareup.com/docs/gift-cards/using-gift-cards-api#third-party-gift-cards).
   */
  Other: "OTHER",
} as const;
export type GiftCardGanSource = (typeof GiftCardGanSource)[keyof typeof GiftCardGanSource] | (string & {});

export const giftCardGanSourceSchema: EnumSchema<GiftCardGanSource> =
  s.enumOf<GiftCardGanSource>(GiftCardGanSource);
